insert into public.god_time_messages ("year","month","published","title","subtitle","verse","verseText","author","body","memoryVerse","memoryText","visible_from","visible_until") values (5787,'cheshvan',true,'FAITHFULNESS IN THE HIDDEN SEASON','Setia Menyelesaikan Apa yang Tuhan Percayakan','1 Raja-raja 6:38','Dan dalam tahun yang kesebelas, dalam bulan Bul, yaitu bulan kedelapan, selesailah rumah itu dengan segala bagian-bagiannya dan sesuai dengan segala rancangannya; jadi tujuh tahun lamanya ia mendirikan rumah itu.','El - Bethel House Of Prayer','Memasuki bulan Cheshvan 5787, kita diingatkan bahwa Tuhan memiliki rancangan dan waktu untuk setiap pekerjaan yang Ia percayakan kepada kita. Seperti Salomo yang membangun Bait Suci sesuai dengan segala rancangannya hingga selesai, demikian pula kita dipanggil bukan hanya untuk memulai apa yang Tuhan percayakan, tetapi juga untuk setia menyelesaikannya sesuai dengan kehendak-Nya.

Bulan Cheshvan ini membawa kita memasuki musim yang lebih sunyi setelah rangkaian perayaan di bulan Tishrei. Dalam musim ini, kesetiaan kita diuji: apakah kita tetap taat ketika tidak ada sorotan, tetap tekun ketika hasil belum terlihat, dan tetap mengerjakan bagian kita meskipun prosesnya terasa panjang. Sebab kesetiaan sejati tidak hanya terlihat saat kita memulai dengan semangat, tetapi juga ketika kita bertahan dalam proses hingga pekerjaan itu selesai.

Blueprint ilahi sudah diberikan; sekarang waktunya kita berjalan dalam kesetiaan untuk menyelesaikan apa yang Tuhan percayakan. Jangan meremehkan proses yang sedang kita jalani, sebab setiap langkah ketaatan merupakan bagian dari penggenapan rancangan-Nya. Tetaplah setia dalam musim tersembunyi, karena Tuhan sedang membawa setiap pekerjaan menuju penyelesaian sesuai dengan waktu dan kehendak-Nya.

Faithfulness in the Hidden Season, tetap setia sampai setiap bagian dari rancangan Tuhan diselesaikan dan dinyatakan. Amen!!!','1 Raja-raja 6:38','Dan dalam tahun yang kesebelas, dalam bulan Bul, yaitu bulan kedelapan, selesailah rumah itu dengan segala bagian-bagiannya dan sesuai dengan segala rancangannya; jadi tujuh tahun lamanya ia mendirikan rumah itu.','2026-10-11T10:45:28.331Z','2026-11-10T10:47:49.920Z') on conflict (year,month) do nothing;
commit;
